action.code:
while (usage_ > target_usage && lru_.next != &lru_) {
    LRUHandle* old = lru_.next;
    // Remove from LRU list
    LRU_Remove(old);
    // Remove from hash table
    table_.Remove(old->key(), old->hash);
    // Release reference; may delete the entry
    Unref(old);
    usage_ -= old->charge;
}

